/usr/bin/bash -lc "timeout 20s python - <<'PY'
import asyncio
from starlette.websockets import WebSocket, WebSocketDisconnect, WebSocketDisconnected, WebSocketState

scope = {\"type\": \"websocket\", \"path\": \"/\", \"headers\": []}

async def no_receive():
    raise AssertionError(\"unexpected receive\")

async def no_send(message):
    raise AssertionError(\"unexpected send\")

async def main():
    assert issubclass(WebSocketDisconnected, RuntimeError)
    assert WebSocketDisconnected is not RuntimeError

    websocket = WebSocket(scope, no_receive, no_send)
    websocket.client_state = WebSocketState.DISCONNECTED
    try:
        await websocket.receive()
    except WebSocketDisconnected as exc:
        assert str(exc) == 'Cannot call \"receive\" once a disconnect message has been received.'
    else:
        raise AssertionError(\"disconnected receive did not fail\")

    websocket = WebSocket(scope, no_receive, no_send)
    websocket.application_state = WebSocketState.DISCONNECTED
    try:
        await websocket.send({\"type\": \"websocket.send\", \"text\": \"x\"})
    except WebSocketDisconnected as exc:
        assert str(exc) == 'Cannot call \"send\" once a close message has been sent.'
    else:
        raise AssertionError(\"disconnected send did not fail\")

    for method, args in ((\"receive_text\", ()), (\"receive_bytes\", ()), (\"receive_json\", ()), (\"receive_json\", (\"binary\",))):
        websocket = WebSocket(scope, no_receive, no_send)
        websocket.application_state = WebSocketState.DISCONNECTED
        try:
            await getattr(websocket, method)(*args)
        except WebSocketDisconnected as exc:
            assert str(exc) == 'WebSocket is not connected. Need to call \"accept\" first.'
        else:
            raise AssertionError(f\"{method} did not fail\")

    websocket = WebSocket(scope, no_receive, no_send)
    websocket.application_state = WebSocketState.DISCONNECTED
    try:
        await websocket.receive_json(\"invalid\")
    except RuntimeError as exc:
        assert type(exc) is RuntimeError
    else:
        raise AssertionError(\"invalid mode did not fail\")

    async def bad_receive():
        return {\"type\": \"websocket.receive\"}

    websocket = WebSocket(scope, bad_receive, no_send)
    try:
        await websocket.receive()
    except RuntimeError as exc:
        assert type(exc) is RuntimeError
    else:
        raise AssertionError(\"invalid receive protocol did not fail\")

    websocket = WebSocket(scope, no_receive, no_send)
    try:
        await websocket.send({\"type\": \"websocket.send\", \"text\": \"x\"})
    except RuntimeError as exc:
        assert type(exc) is RuntimeError
    else:
        raise AssertionError(\"invalid send protocol did not fail\")

    async def peer_disconnect():
        return {\"type\": \"websocket.disconnect\", \"code\": 1001, \"reason\": \"bye\"}

    websocket = WebSocket(scope, peer_disconnect, no_send)
    websocket.client_state = WebSocketState.CONNECTED
    websocket.application_state = WebSocketState.CONNECTED
    try:
        await websocket.receive_text()
    except WebSocketDisconnect as exc:
        assert type(exc) is WebSocketDisconnect
        assert (exc.code, exc.reason) == (1001, \"bye\")
    else:
        raise AssertionError(\"peer disconnect did not fail\")

asyncio.run(main())
PY"

